insert into public.hexagram_lines
  (hexagram_number, line_number, source_text, translation_vi, source_name, source_url, review_status)
values
  (1, 1, '初九：潛龍勿用。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E4%B9%BE', 'source_only'),
  (1, 2, '九二：見龍在田，利見大人。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E4%B9%BE', 'source_only'),
  (1, 3, '九三：君子終日乾乾，夕惕若；厲，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E4%B9%BE', 'source_only'),
  (1, 4, '九四：或躍在淵，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E4%B9%BE', 'source_only'),
  (1, 5, '九五：飛龍在天，利見大人。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E4%B9%BE', 'source_only'),
  (1, 6, '上九：亢龍，有悔。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E4%B9%BE', 'source_only'),
  (2, 1, '初六：履霜，堅冰至。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%9D%A4', 'source_only'),
  (2, 2, '六二：直方大，不習无不利。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%9D%A4', 'source_only'),
  (2, 3, '六三：含章，可貞。或從王事，无成有終。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%9D%A4', 'source_only'),
  (2, 4, '六四：括囊，无咎无譽。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%9D%A4', 'source_only'),
  (2, 5, '六五：黃裳，元吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%9D%A4', 'source_only'),
  (2, 6, '上六：龍戰于野，其血玄黃。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%9D%A4', 'source_only'),
  (3, 1, '初九：磐桓，利居貞，利建侯。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B1%AF', 'source_only'),
  (3, 2, '六二：屯如邅如，乘馬班如，匪寇婚媾，女子貞不字，十年乃字。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B1%AF', 'source_only'),
  (3, 3, '六三：即鹿无虞，惟入于林中，君子幾不如舍，往吝。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B1%AF', 'source_only'),
  (3, 4, '六四：乘馬班如，求婚媾，往，吉无不利。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B1%AF', 'source_only'),
  (3, 5, '九五：屯其膏；小貞吉，大貞凶。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B1%AF', 'source_only'),
  (3, 6, '上六：乘馬班如，泣血漣如。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B1%AF', 'source_only'),
  (4, 1, '初六：發蒙，利用刑人，用說桎梏，以往吝。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%92%99', 'source_only'),
  (4, 2, '九二：包蒙吉，納婦吉，子克家。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%92%99', 'source_only'),
  (4, 3, '六三：勿用取女，見金夫，不有躬，无攸利。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%92%99', 'source_only'),
  (4, 4, '六四：困蒙，吝。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%92%99', 'source_only'),
  (4, 5, '六五：童蒙，吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%92%99', 'source_only'),
  (4, 6, '上九：擊蒙，不利為寇，利禦寇。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%92%99', 'source_only'),
  (5, 1, '初九：需于郊，利用恆，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9C%80', 'source_only'),
  (5, 2, '九二：需于沙，小有言，終吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9C%80', 'source_only'),
  (5, 3, '九三：需于泥，致寇至。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9C%80', 'source_only'),
  (5, 4, '六四：需于血，出自穴。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9C%80', 'source_only'),
  (5, 5, '九五：需于酒食，貞吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9C%80', 'source_only'),
  (5, 6, '上六：入于穴，有不速之客三人來，敬之終吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9C%80', 'source_only'),
  (6, 1, '初六：不永所事，小有言，終吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%A8%9F', 'source_only'),
  (6, 2, '九二：不克訟，歸而逋，其邑人三百戶无眚。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%A8%9F', 'source_only'),
  (6, 3, '六三：食舊德，貞厲，終吉。或從王事，无成。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%A8%9F', 'source_only'),
  (6, 4, '九四：不克訟，復即命渝，安貞吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%A8%9F', 'source_only'),
  (6, 5, '九五：訟，元吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%A8%9F', 'source_only'),
  (6, 6, '上九：或錫之鞶帶，終朝三褫之。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%A8%9F', 'source_only'),
  (7, 1, '初六：師出以律，否臧，凶。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B8%AB', 'source_only'),
  (7, 2, '九二：在師中吉，无咎；王三錫命。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B8%AB', 'source_only'),
  (7, 3, '六三：師或輿尸，凶。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B8%AB', 'source_only'),
  (7, 4, '六四：師左次，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B8%AB', 'source_only'),
  (7, 5, '六五：田有禽，利執言，无咎。長子帥師，弟子輿尸，貞凶。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B8%AB', 'source_only'),
  (7, 6, '上六：大君有命，開國承家，小人勿用。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B8%AB', 'source_only'),
  (8, 1, '初六：有孚，比之，无咎。有孚盈缶，終來有它，吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%AF%94', 'source_only'),
  (8, 2, '六二：比之自內，貞吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%AF%94', 'source_only'),
  (8, 3, '六三：比之匪人。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%AF%94', 'source_only'),
  (8, 4, '六四：外比之，貞吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%AF%94', 'source_only'),
  (8, 5, '九五：顯比。王用三驅，失前禽，邑人不誡，吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%AF%94', 'source_only'),
  (8, 6, '上六：比之无首，凶。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%AF%94', 'source_only'),
  (9, 1, '初九：復自道，何其咎，吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B0%8F%E7%95%9C', 'source_only'),
  (9, 2, '九二：牽復，吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B0%8F%E7%95%9C', 'source_only'),
  (9, 3, '九三：輿說輻，夫妻反目。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B0%8F%E7%95%9C', 'source_only'),
  (9, 4, '六四：有孚，血去惕出，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B0%8F%E7%95%9C', 'source_only'),
  (9, 5, '九五：有孚攣如，富以其鄰。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B0%8F%E7%95%9C', 'source_only'),
  (9, 6, '上九：既雨既處，尚德載，婦貞厲，月幾望，君子征凶。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B0%8F%E7%95%9C', 'source_only'),
  (10, 1, '初九：素履，往无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B1%A5', 'source_only'),
  (10, 2, '九二：履道坦坦，幽人貞吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B1%A5', 'source_only'),
  (10, 3, '六三：眇能視，跛能履，履虎尾，咥人，凶。武人為于大君。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B1%A5', 'source_only'),
  (10, 4, '九四：履虎尾，愬愬終吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B1%A5', 'source_only'),
  (10, 5, '九五：夬履，貞厲。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B1%A5', 'source_only'),
  (10, 6, '上九：視履考祥，其旋元吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B1%A5', 'source_only'),
  (11, 1, '初九：拔茅茹以其彙，征吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%B3%B0', 'source_only'),
  (11, 2, '九二：包荒。用馮河，不遐遺；朋亡。得尚于中行。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%B3%B0', 'source_only'),
  (11, 3, '九三：无平不陂，无往不復，艱貞无咎。勿恤其孚，于食有福。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%B3%B0', 'source_only'),
  (11, 4, '六四：翩翩，不富以其鄰；不戒以孚。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%B3%B0', 'source_only'),
  (11, 5, '六五：帝乙歸妹，以祉，元吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%B3%B0', 'source_only'),
  (11, 6, '上六：城復于隍，勿用師，自邑告命，貞吝。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%B3%B0', 'source_only'),
  (12, 1, '初六，拔茅茹以其彙，貞吉。亨。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%90%A6', 'source_only'),
  (12, 2, '六二，包承，小人吉，大人否。亨。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%90%A6', 'source_only'),
  (12, 3, '六三，包羞。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%90%A6', 'source_only'),
  (12, 4, '九四，有命，无咎，疇離祉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%90%A6', 'source_only'),
  (12, 5, '九五，休否，大人吉。其亡其亡，繫于苞桑。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%90%A6', 'source_only'),
  (12, 6, '上九，傾否，先否後喜。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%90%A6', 'source_only'),
  (13, 1, '初九：同人于門，無咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%90%8C%E4%BA%BA', 'source_only'),
  (13, 2, '六二：同人于宗，吝。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%90%8C%E4%BA%BA', 'source_only'),
  (13, 3, '九三：伏戎于莽，升其高陵，三歲不興。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%90%8C%E4%BA%BA', 'source_only'),
  (13, 4, '九四：乘其墉，弗克，攻吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%90%8C%E4%BA%BA', 'source_only'),
  (13, 5, '九五：同人，先號啕而后笑。大師克相遇。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%90%8C%E4%BA%BA', 'source_only'),
  (13, 6, '上九：同人于郊，無悔。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%90%8C%E4%BA%BA', 'source_only'),
  (14, 1, '初九：无交害，匪咎，艱則无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%A7%E6%9C%89', 'source_only'),
  (14, 2, '九二：大車以載，有攸往，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%A7%E6%9C%89', 'source_only'),
  (14, 3, '九三：公用亨于天子，小人弗克。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%A7%E6%9C%89', 'source_only'),
  (14, 4, '九四：匪其彭，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%A7%E6%9C%89', 'source_only'),
  (14, 5, '六五：厥孚交如，威如；吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%A7%E6%9C%89', 'source_only'),
  (14, 6, '上九：自天佑之，吉无不利。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%A7%E6%9C%89', 'source_only'),
  (15, 1, '初六：謙謙君子，用涉大川，吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%AC%99', 'source_only'),
  (15, 2, '六二：鳴謙，貞吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%AC%99', 'source_only'),
  (15, 3, '九三：勞謙君子，有終吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%AC%99', 'source_only'),
  (15, 4, '六四：无不利，撝謙。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%AC%99', 'source_only'),
  (15, 5, '六五：不富，以其鄰，利用侵伐，无不利。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%AC%99', 'source_only'),
  (15, 6, '上六：鳴謙，利用行師，征邑國。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%AC%99', 'source_only'),
  (16, 1, '初六：鳴豫，凶。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%B1%AB', 'source_only'),
  (16, 2, '六二：介于石，不終日，貞吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%B1%AB', 'source_only'),
  (16, 3, '六三：盱豫，悔。遲有悔。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%B1%AB', 'source_only'),
  (16, 4, '九四：由豫，大有得。勿疑。朋盍簪。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%B1%AB', 'source_only'),
  (16, 5, '六五：貞疾，恆不死。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%B1%AB', 'source_only'),
  (16, 6, '上六：冥豫，成有渝，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%B1%AB', 'source_only'),
  (17, 1, '初九：官有渝，貞吉。出門交有功。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9A%A8', 'source_only'),
  (17, 2, '六二：系小子，失丈夫。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9A%A8', 'source_only'),
  (17, 3, '六三：系丈夫，失小子。隨，有求得利，居貞。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9A%A8', 'source_only'),
  (17, 4, '九四：隨有獲，貞凶。有孚在道，以明，何咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9A%A8', 'source_only'),
  (17, 5, '九五：孚于嘉，吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9A%A8', 'source_only'),
  (17, 6, '上六：拘系之，乃從維之。王用亨于西山。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9A%A8', 'source_only'),
  (18, 1, '初六：幹父之蠱，有子考，无咎，厲終吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%A0%B1', 'source_only'),
  (18, 2, '九二：幹母之蠱，不可貞。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%A0%B1', 'source_only'),
  (18, 3, '九三：幹父之蠱，小有悔，无大咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%A0%B1', 'source_only'),
  (18, 4, '六四：裕父之蠱，往見吝。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%A0%B1', 'source_only'),
  (18, 5, '六五：幹父之蠱，用譽。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%A0%B1', 'source_only'),
  (18, 6, '上九：不事王侯，高尚其事。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%A0%B1', 'source_only'),
  (19, 1, '初九：咸臨，貞吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%87%A8', 'source_only'),
  (19, 2, '九二：咸臨，吉无不利。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%87%A8', 'source_only'),
  (19, 3, '六三：甘臨，无攸利。既憂之，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%87%A8', 'source_only'),
  (19, 4, '六四：至臨，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%87%A8', 'source_only'),
  (19, 5, '六五：知臨，大君之宜，吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%87%A8', 'source_only'),
  (19, 6, '上六：敦臨，吉无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%87%A8', 'source_only'),
  (20, 1, '初六：童觀，小人无咎，君子吝。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%A7%80', 'source_only'),
  (20, 2, '六二：窺觀，利女貞。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%A7%80', 'source_only'),
  (20, 3, '六三：觀我生，進退。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%A7%80', 'source_only'),
  (20, 4, '六四：觀國之光，利用賓于王。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%A7%80', 'source_only'),
  (20, 5, '九五：觀我生，君子无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%A7%80', 'source_only'),
  (20, 6, '上九：觀其生，君子无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%A7%80', 'source_only'),
  (21, 1, '初九：屨校滅趾，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%99%AC%E5%97%91', 'source_only'),
  (21, 2, '六二：噬膚滅鼻，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%99%AC%E5%97%91', 'source_only'),
  (21, 3, '六三：噬臘肉，遇毒；小吝，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%99%AC%E5%97%91', 'source_only'),
  (21, 4, '九四：噬乾胏，得金矢，利艱貞，吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%99%AC%E5%97%91', 'source_only'),
  (21, 5, '六五：噬乾肉，得黃金，貞厲，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%99%AC%E5%97%91', 'source_only'),
  (21, 6, '上九：何校滅耳，凶。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%99%AC%E5%97%91', 'source_only'),
  (22, 1, '初九：賁其趾，舍車而徒。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%B3%81', 'source_only'),
  (22, 2, '六二：賁其須。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%B3%81', 'source_only'),
  (22, 3, '九三：賁如濡如，永貞吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%B3%81', 'source_only'),
  (22, 4, '六四：賁如皤如，白馬翰如，匪寇婚媾。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%B3%81', 'source_only'),
  (22, 5, '六五：賁於丘園，束帛戔戔，吝，終吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%B3%81', 'source_only'),
  (22, 6, '上九：白賁，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%B3%81', 'source_only'),
  (23, 1, '初六：剝牀以足，蔑貞凶。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%89%9D', 'source_only'),
  (23, 2, '六二：剝牀以辨，蔑貞凶。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%89%9D', 'source_only'),
  (23, 3, '六三：剝之，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%89%9D', 'source_only'),
  (23, 4, '六四：剝牀以膚，凶。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%89%9D', 'source_only'),
  (23, 5, '六五：貫魚，以宮人寵，无不利。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%89%9D', 'source_only'),
  (23, 6, '上九：碩果不食，君子得輿，小人剝廬。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%89%9D', 'source_only'),
  (24, 1, '初九：不復遠，无袛悔，元吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%BE%A9', 'source_only'),
  (24, 2, '六二：休復，吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%BE%A9', 'source_only'),
  (24, 3, '六三：頻復，厲无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%BE%A9', 'source_only'),
  (24, 4, '六四：中行獨復。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%BE%A9', 'source_only'),
  (24, 5, '六五：敦復，无悔。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%BE%A9', 'source_only'),
  (24, 6, '上六：迷復，凶，有災眚。用行師，終有大敗，以其國君，凶；至于十年，不克征。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%BE%A9', 'source_only'),
  (25, 1, '初九：无妄，往吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%97%A0%E5%A6%84', 'source_only'),
  (25, 2, '六二：不耕穫，不菑畬，則利有攸往。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%97%A0%E5%A6%84', 'source_only'),
  (25, 3, '六三：无妄之災，或系之牛，行人之得，邑人之災。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%97%A0%E5%A6%84', 'source_only'),
  (25, 4, '九四：可貞，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%97%A0%E5%A6%84', 'source_only'),
  (25, 5, '九五：无妄之疾，勿藥有喜。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%97%A0%E5%A6%84', 'source_only'),
  (25, 6, '上九：无妄，行有眚，无攸利。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%97%A0%E5%A6%84', 'source_only'),
  (26, 1, '初九：有厲利已。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%A7%E7%95%9C', 'source_only'),
  (26, 2, '九二：輿說輹。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%A7%E7%95%9C', 'source_only'),
  (26, 3, '九三：良馬逐，利艱貞。曰閑輿衛，利有攸往。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%A7%E7%95%9C', 'source_only'),
  (26, 4, '六四：童牛之牿，元吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%A7%E7%95%9C', 'source_only'),
  (26, 5, '六五：豶豕之牙，吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%A7%E7%95%9C', 'source_only'),
  (26, 6, '上九：何天之衢，亨。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%A7%E7%95%9C', 'source_only'),
  (27, 1, '初九：舍爾靈龜，觀我朵頤，凶。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%A0%A4', 'source_only'),
  (27, 2, '六二：顛頤，拂經，于丘頤，征凶。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%A0%A4', 'source_only'),
  (27, 3, '六三：拂頤，貞凶，十年勿用，无攸利。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%A0%A4', 'source_only'),
  (27, 4, '六四：顛頤吉，虎視眈眈，其欲逐逐，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%A0%A4', 'source_only'),
  (27, 5, '六五：拂經，居貞吉，不可涉大川。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%A0%A4', 'source_only'),
  (27, 6, '上九：由頤，厲吉，利涉大川。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%A0%A4', 'source_only'),
  (28, 1, '初六：藉用白茅，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%A7%E9%81%8E', 'source_only'),
  (28, 2, '九二：枯楊生稊，老夫得其女妻，无不利。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%A7%E9%81%8E', 'source_only'),
  (28, 3, '九三：棟橈，凶。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%A7%E9%81%8E', 'source_only'),
  (28, 4, '九四：棟隆，吉。有它吝。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%A7%E9%81%8E', 'source_only'),
  (28, 5, '九五：枯楊生華，老婦得其士夫，无咎无譽。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%A7%E9%81%8E', 'source_only'),
  (28, 6, '上六：過涉滅頂，凶，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%A7%E9%81%8E', 'source_only'),
  (29, 1, '初六：習坎，入于坎窞，凶。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%9D%8E', 'source_only'),
  (29, 2, '九二：坎有險，求小得。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%9D%8E', 'source_only'),
  (29, 3, '六三：來之坎坎，險且枕，入于坎窞，勿用。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%9D%8E', 'source_only'),
  (29, 4, '六四：樽酒簋貳，用缶，納約自牖，終无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%9D%8E', 'source_only'),
  (29, 5, '九五：坎不盈，祗既平，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%9D%8E', 'source_only'),
  (29, 6, '上六：係用徽纆，寘于叢棘，三歲不得，凶。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%9D%8E', 'source_only'),
  (30, 1, '初九：履錯然，敬之无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9B%A2', 'source_only'),
  (30, 2, '六二：黃離，元吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9B%A2', 'source_only'),
  (30, 3, '九三：日昃之離，不鼓缶而歌，則大耋之嗟，凶。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9B%A2', 'source_only'),
  (30, 4, '九四：突如其來如，焚如，死如，棄如。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9B%A2', 'source_only'),
  (30, 5, '六五：出涕沱若，戚嗟若，吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9B%A2', 'source_only'),
  (30, 6, '上九：王用出征，有嘉折首，獲匪其醜，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9B%A2', 'source_only'),
  (31, 1, '初六：咸其拇。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%92%B8', 'source_only'),
  (31, 2, '六二：咸其腓，凶，居吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%92%B8', 'source_only'),
  (31, 3, '九三：咸其股，執其隨，往吝。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%92%B8', 'source_only'),
  (31, 4, '九四：貞吉悔亡，憧憧往來，朋從爾思。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%92%B8', 'source_only'),
  (31, 5, '九五：咸其脢，无悔。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%92%B8', 'source_only'),
  (31, 6, '上六：咸其輔，頰，舌。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%92%B8', 'source_only'),
  (32, 1, '初六：浚恆，貞凶，无攸利。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%81%92', 'source_only'),
  (32, 2, '九二：悔亡。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%81%92', 'source_only'),
  (32, 3, '九三：不恆其德，或承之羞，貞吝。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%81%92', 'source_only'),
  (32, 4, '九四：田无禽。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%81%92', 'source_only'),
  (32, 5, '六五：恆其德，貞，婦人吉，夫子凶。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%81%92', 'source_only'),
  (32, 6, '上六：振恆，凶。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%81%92', 'source_only'),
  (33, 1, '初六：遯尾，厲，勿用有攸往。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%81%AF', 'source_only'),
  (33, 2, '六二：執之用黃牛之革，莫之勝說。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%81%AF', 'source_only'),
  (33, 3, '九三：系遯，有疾厲，畜臣妾吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%81%AF', 'source_only'),
  (33, 4, '九四：好遯君子吉，小人否。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%81%AF', 'source_only'),
  (33, 5, '九五：嘉遯，貞吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%81%AF', 'source_only'),
  (33, 6, '上九：肥遯，无不利。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%81%AF', 'source_only'),
  (34, 1, '初九：壯于趾，征凶，有孚。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%A7%E5%A3%AF', 'source_only'),
  (34, 2, '九二：貞吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%A7%E5%A3%AF', 'source_only'),
  (34, 3, '九三：小人用壯，君子用罔，貞厲。羝羊觸藩，羸其角。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%A7%E5%A3%AF', 'source_only'),
  (34, 4, '九四：貞吉悔亡，藩決不羸，壯于大輿之輹。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%A7%E5%A3%AF', 'source_only'),
  (34, 5, '六五：喪羊于易，无悔。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%A7%E5%A3%AF', 'source_only'),
  (34, 6, '上六：羝羊觸藩，不能退，不能遂，无攸利，艱則吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%A7%E5%A3%AF', 'source_only'),
  (35, 1, '初六：晉如，摧如，貞吉。罔孚，裕无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%99%89', 'source_only'),
  (35, 2, '六二：晉如，愁如，貞吉。受茲介福，于其王母。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%99%89', 'source_only'),
  (35, 3, '六三：眾允，悔亡。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%99%89', 'source_only'),
  (35, 4, '九四：晉如鼫鼠，貞厲。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%99%89', 'source_only'),
  (35, 5, '六五：悔亡，失得勿恤，往吉无不利。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%99%89', 'source_only'),
  (35, 6, '上九：晉其角，維用伐邑，厲吉无咎，貞吝。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%99%89', 'source_only'),
  (36, 1, '初九：明夷于飛，垂其翼。君子于行，三日不食，有攸往，主人有言。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%98%8E%E5%A4%B7', 'source_only'),
  (36, 2, '六二：明夷，夷于左股，用拯馬壯，吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%98%8E%E5%A4%B7', 'source_only'),
  (36, 3, '九三：明夷于南狩，得其大首，不可疾貞。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%98%8E%E5%A4%B7', 'source_only'),
  (36, 4, '六四：入于左腹，獲明夷之心，于出門庭。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%98%8E%E5%A4%B7', 'source_only'),
  (36, 5, '六五：箕子之明夷，利貞。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%98%8E%E5%A4%B7', 'source_only'),
  (36, 6, '上六：不明晦，初登于天，后入于地。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%98%8E%E5%A4%B7', 'source_only'),
  (37, 1, '初九：閑有家，悔亡。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%AE%B6%E4%BA%BA', 'source_only'),
  (37, 2, '六二：无攸遂，在中饋，貞吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%AE%B6%E4%BA%BA', 'source_only'),
  (37, 3, '九三：家人嗃嗃，悔厲吉；婦子嘻嘻，終吝。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%AE%B6%E4%BA%BA', 'source_only'),
  (37, 4, '六四：富家，大吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%AE%B6%E4%BA%BA', 'source_only'),
  (37, 5, '九五：王假有家，勿恤。吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%AE%B6%E4%BA%BA', 'source_only'),
  (37, 6, '上九：有孚威如，終吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%AE%B6%E4%BA%BA', 'source_only'),
  (38, 1, '初九：悔亡，喪馬勿逐，自復；見惡人无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E7%9D%BD', 'source_only'),
  (38, 2, '九二：遇主于巷，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E7%9D%BD', 'source_only'),
  (38, 3, '六三：見輿曳，其牛掣，其人天且劓，无初有終。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E7%9D%BD', 'source_only'),
  (38, 4, '九四：睽孤，遇元夫，交孚，厲无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E7%9D%BD', 'source_only'),
  (38, 5, '六五：悔亡，厥宗噬膚，往何咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E7%9D%BD', 'source_only'),
  (38, 6, '上九：睽孤， 見豕負涂，載鬼一車， 先張之弧，后說之弧，匪寇婚媾，往遇雨則吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E7%9D%BD', 'source_only'),
  (39, 1, '初六：往蹇，來譽。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%B9%87', 'source_only'),
  (39, 2, '六二：王臣蹇蹇，匪躬之故。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%B9%87', 'source_only'),
  (39, 3, '九三：往蹇來反。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%B9%87', 'source_only'),
  (39, 4, '六四：往蹇來連。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%B9%87', 'source_only'),
  (39, 5, '九五：大蹇朋來。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%B9%87', 'source_only'),
  (39, 6, '上六：往蹇來碩，吉；利見大人。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%B9%87', 'source_only'),
  (40, 1, '初六：无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%A7%A3', 'source_only'),
  (40, 2, '九二：田獲三狐，得黃矢，貞吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%A7%A3', 'source_only'),
  (40, 3, '六三：負且乘，致寇至，貞吝。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%A7%A3', 'source_only'),
  (40, 4, '九四：解而拇，朋至斯孚。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%A7%A3', 'source_only'),
  (40, 5, '六五：君子維有解，吉；有孚于小人。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%A7%A3', 'source_only'),
  (40, 6, '上六：公用射隼，于高墉之上，獲之，无不利。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%A7%A3', 'source_only'),
  (41, 1, '初九：已事遄往，无咎，酌損之。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%90%8D', 'source_only'),
  (41, 2, '九二：利貞，征凶，弗損益之。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%90%8D', 'source_only'),
  (41, 3, '六三：三人行，則損一人；一人行，則得其友。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%90%8D', 'source_only'),
  (41, 4, '六四：損其疾，使遄有喜，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%90%8D', 'source_only'),
  (41, 5, '六五：或益之，十朋之龜弗克違，元吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%90%8D', 'source_only'),
  (41, 6, '上九：弗損益之，无咎，貞吉，利有攸往，得臣无家。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%90%8D', 'source_only'),
  (42, 1, '初九：利用為大作，元吉，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E7%9B%8A', 'source_only'),
  (42, 2, '六二：或益之，十朋之龜弗克違，永貞吉。王用享于帝，吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E7%9B%8A', 'source_only'),
  (42, 3, '六三：益之用凶事，无咎。有孚中行，告公用圭。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E7%9B%8A', 'source_only'),
  (42, 4, '六四：中行，告公從。利用為依遷國。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E7%9B%8A', 'source_only'),
  (42, 5, '九五：有孚惠心，勿問元吉。有孚惠我德。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E7%9B%8A', 'source_only'),
  (42, 6, '上九：莫益之，或擊之，立心勿恆，凶。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E7%9B%8A', 'source_only'),
  (43, 1, '初九：壯于前趾，往不勝為咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%AC', 'source_only'),
  (43, 2, '九二：惕號，莫夜有戎，勿恤。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%AC', 'source_only'),
  (43, 3, '九三：壯于頄，有凶。君子夬夬，獨行遇雨，若濡有慍，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%AC', 'source_only'),
  (43, 4, '九四：臀无膚，其行次且。牽羊悔亡，聞言不信。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%AC', 'source_only'),
  (43, 5, '九五：莧陸夬夬，中行无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%AC', 'source_only'),
  (43, 6, '上六：无號，終有凶。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%AC', 'source_only'),
  (44, 1, '初六：系于金柅，貞吉，有攸往，見凶，羸豕孚踟躅。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A7%A4', 'source_only'),
  (44, 2, '九二：包有魚，无咎，不利賓。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A7%A4', 'source_only'),
  (44, 3, '九三：臀无膚，其行次且，厲，无大咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A7%A4', 'source_only'),
  (44, 4, '九四：包无魚，起凶。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A7%A4', 'source_only'),
  (44, 5, '九五：以杞包瓜，含章，有隕自天。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A7%A4', 'source_only'),
  (44, 6, '上九：姤其角，吝，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A7%A4', 'source_only'),
  (45, 1, '初六：有孚不終，乃亂乃萃，若號一握為笑，勿恤，往无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%90%83', 'source_only'),
  (45, 2, '六二：引吉，无咎，孚乃利用禴。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%90%83', 'source_only'),
  (45, 3, '六三：萃如，嗟如，无攸利，往无咎，小吝。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%90%83', 'source_only'),
  (45, 4, '九四：大吉，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%90%83', 'source_only'),
  (45, 5, '九五：萃有位，无咎。匪孚，元永貞，悔亡。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%90%83', 'source_only'),
  (45, 6, '上六：齎咨涕洟，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%90%83', 'source_only'),
  (46, 1, '初六：允升，大吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%8D%87', 'source_only'),
  (46, 2, '九二：孚乃利用禴，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%8D%87', 'source_only'),
  (46, 3, '九三：升虛邑。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%8D%87', 'source_only'),
  (46, 4, '六四：王用亨于岐山，吉无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%8D%87', 'source_only'),
  (46, 5, '六五：貞吉，升階。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%8D%87', 'source_only'),
  (46, 6, '上六：冥升，利于不息之貞。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%8D%87', 'source_only'),
  (47, 1, '初六：臀困于株木，入于幽谷，三歲不覿。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%9B%B0', 'source_only'),
  (47, 2, '九二：困于酒食，朱紱方來，利用亨祀，征凶，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%9B%B0', 'source_only'),
  (47, 3, '六三：困于石，據于蒺藜，入于其宮，不見其妻，凶。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%9B%B0', 'source_only'),
  (47, 4, '九四：來徐徐，困于金車，吝，有終。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%9B%B0', 'source_only'),
  (47, 5, '九五：劓刖，困于赤紱，乃徐有說，利用祭祀。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%9B%B0', 'source_only'),
  (47, 6, '上六：困于葛藟，于臲卼，曰動悔。有悔，征吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%9B%B0', 'source_only'),
  (48, 1, '初六：井泥不食，舊井无禽。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E4%BA%95', 'source_only'),
  (48, 2, '九二：井谷射鮒，瓮敝漏。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E4%BA%95', 'source_only'),
  (48, 3, '九三：井渫不食，為我心惻，可用汲，王明，并受其福。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E4%BA%95', 'source_only'),
  (48, 4, '六四：井甃，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E4%BA%95', 'source_only'),
  (48, 5, '九五：井冽，寒泉食。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E4%BA%95', 'source_only'),
  (48, 6, '上六：井收勿幕，有孚元吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E4%BA%95', 'source_only'),
  (49, 1, '初九：鞏用黃牛之革。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9D%A9', 'source_only'),
  (49, 2, '六二：巳日乃革之，征吉，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9D%A9', 'source_only'),
  (49, 3, '九三：征凶，貞厲，革言三就，有孚。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9D%A9', 'source_only'),
  (49, 4, '九四：悔亡，有孚改命，吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9D%A9', 'source_only'),
  (49, 5, '九五：大人虎變，未占有孚。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9D%A9', 'source_only'),
  (49, 6, '上六：君子豹變，小人革面，征凶，居貞吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9D%A9', 'source_only'),
  (50, 1, '初六：鼎顛趾，利出否，得妾以其子，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%BC%8E', 'source_only'),
  (50, 2, '九二：鼎有實，我仇有疾，不我能即，吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%BC%8E', 'source_only'),
  (50, 3, '九三：鼎耳革，其行塞，雉膏不食，方雨虧悔，終吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%BC%8E', 'source_only'),
  (50, 4, '九四：鼎折足，覆公餗，其形渥，凶。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%BC%8E', 'source_only'),
  (50, 5, '六五：鼎黃耳金鉉，利貞。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%BC%8E', 'source_only'),
  (50, 6, '上九：鼎玉鉉，大吉，无不利。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%BC%8E', 'source_only'),
  (51, 1, '初九：震來虩虩，后笑言啞啞，吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9C%87', 'source_only'),
  (51, 2, '六二：震來厲，億喪貝，躋于九陵，勿逐，七日得。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9C%87', 'source_only'),
  (51, 3, '六三：震蘇蘇，震行无眚。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9C%87', 'source_only'),
  (51, 4, '九四：震遂泥。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9C%87', 'source_only'),
  (51, 5, '六五：震往來厲，億无喪，有事。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9C%87', 'source_only'),
  (51, 6, '上六：震索索，視矍矍，征凶。震不于其躬，于其鄰，无咎。婚媾有言。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9C%87', 'source_only'),
  (52, 1, '初六：艮其趾，无咎，利永貞。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%89%AE', 'source_only'),
  (52, 2, '六二：艮其腓，不拯其隨，其心不快。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%89%AE', 'source_only'),
  (52, 3, '九三：艮其限，列其夤，厲薰心。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%89%AE', 'source_only'),
  (52, 4, '六四：艮其身，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%89%AE', 'source_only'),
  (52, 5, '六五：艮其輔，言有序，悔亡。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%89%AE', 'source_only'),
  (52, 6, '上九：敦艮，吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%89%AE', 'source_only'),
  (53, 1, '初六：鴻漸于干，小子厲，有言，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%BC%B8', 'source_only'),
  (53, 2, '六二：鴻漸于磐，飲食衎衎，吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%BC%B8', 'source_only'),
  (53, 3, '九三：鴻漸于陸，夫征不復，婦孕不育，凶；利禦寇。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%BC%B8', 'source_only'),
  (53, 4, '六四：鴻漸于木，或得其桷，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%BC%B8', 'source_only'),
  (53, 5, '九五：鴻漸于陵，婦三歲不孕，終莫之勝，吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%BC%B8', 'source_only'),
  (53, 6, '上九：鴻漸于陸，其羽可用為儀，吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%BC%B8', 'source_only'),
  (54, 1, '初九：歸妹以娣，跛能履，征吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%AD%B8%E5%A6%B9', 'source_only'),
  (54, 2, '九二：眇能視，利幽人之貞。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%AD%B8%E5%A6%B9', 'source_only'),
  (54, 3, '六三：歸妹以須，反歸以娣。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%AD%B8%E5%A6%B9', 'source_only'),
  (54, 4, '九四：歸妹愆期，遲歸有時。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%AD%B8%E5%A6%B9', 'source_only'),
  (54, 5, '六五：帝乙歸妹，其君之袂，不如其娣之袂良，月幾望，吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%AD%B8%E5%A6%B9', 'source_only'),
  (54, 6, '上六：女承筐无實，士刲羊无血，无攸利。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%AD%B8%E5%A6%B9', 'source_only'),
  (55, 1, '初九：遇其配主，雖旬无咎，往有尚。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%B1%90', 'source_only'),
  (55, 2, '六二：豐其蔀，日中見斗，往得疑疾，有孚發若，吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%B1%90', 'source_only'),
  (55, 3, '九三：豐其沛，日中見沫，折其右肱，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%B1%90', 'source_only'),
  (55, 4, '九四：豐其蔀，日中見斗，遇其夷主，吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%B1%90', 'source_only'),
  (55, 5, '六五：來章，有慶譽，吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%B1%90', 'source_only'),
  (55, 6, '上六：豐其屋，蔀其家，窺其戶，闃其无人，三歲不觌，凶。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%B1%90', 'source_only'),
  (56, 1, '初六：旅瑣瑣，斯其所取災。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%97%85', 'source_only'),
  (56, 2, '六二：旅即次，懷其資，得童僕貞。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%97%85', 'source_only'),
  (56, 3, '九三：旅焚其次，喪其童僕，貞厲。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%97%85', 'source_only'),
  (56, 4, '九四：旅于處，得其資斧，我心不快。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%97%85', 'source_only'),
  (56, 5, '六五：射雉一矢亡，終以譽命。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%97%85', 'source_only'),
  (56, 6, '上九：鳥焚其巢，旅人先笑后號咷。喪牛于易，凶。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%97%85', 'source_only'),
  (57, 1, '初六：進退，利武人之貞。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B7%BD', 'source_only'),
  (57, 2, '九二：巽在牀下，用史巫紛若，吉无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B7%BD', 'source_only'),
  (57, 3, '九三：頻巽，吝。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B7%BD', 'source_only'),
  (57, 4, '六四：悔亡，田獲三品。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B7%BD', 'source_only'),
  (57, 5, '九五：貞吉悔亡，无不利。无初有終，先庚三日，后庚三日，吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B7%BD', 'source_only'),
  (57, 6, '上九：巽在牀下，喪其資斧，貞凶。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B7%BD', 'source_only'),
  (58, 1, '初九：和兌，吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%85%8C', 'source_only'),
  (58, 2, '九二：孚兌，吉，悔亡。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%85%8C', 'source_only'),
  (58, 3, '六三：來兌，凶。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%85%8C', 'source_only'),
  (58, 4, '九四：商兌，未寧，介疾有喜。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%85%8C', 'source_only'),
  (58, 5, '九五：孚于剝，有厲。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%85%8C', 'source_only'),
  (58, 6, '上六：引兌。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%85%8C', 'source_only'),
  (59, 1, '初六：用拯馬壯，吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%B8%99', 'source_only'),
  (59, 2, '九二：渙奔其机，悔亡。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%B8%99', 'source_only'),
  (59, 3, '六三：渙其躬，无悔。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%B8%99', 'source_only'),
  (59, 4, '六四：渙其群，元吉。渙有丘，匪夷所思。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%B8%99', 'source_only'),
  (59, 5, '九五：渙汗其大號，渙王居，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%B8%99', 'source_only'),
  (59, 6, '上九：渙其血，去逖出，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%B8%99', 'source_only'),
  (60, 1, '初九：不出戶庭，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E7%AF%80', 'source_only'),
  (60, 2, '九二：不出門庭，凶。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E7%AF%80', 'source_only'),
  (60, 3, '六三：不節若，則嗟若，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E7%AF%80', 'source_only'),
  (60, 4, '六四：安節，亨。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E7%AF%80', 'source_only'),
  (60, 5, '九五：甘節，吉；往有尚。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E7%AF%80', 'source_only'),
  (60, 6, '上六：苦節，貞凶，悔亡。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E7%AF%80', 'source_only'),
  (61, 1, '初九：虞吉，有他不燕。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E4%B8%AD%E5%AD%9A', 'source_only'),
  (61, 2, '九二：鳴鶴在陰，其子和之，我有好爵，吾與爾靡之。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E4%B8%AD%E5%AD%9A', 'source_only'),
  (61, 3, '六三：得敵，或鼓或罷，或泣或歌。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E4%B8%AD%E5%AD%9A', 'source_only'),
  (61, 4, '六四：月几望，馬匹亡，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E4%B8%AD%E5%AD%9A', 'source_only'),
  (61, 5, '九五：有孚攣如，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E4%B8%AD%E5%AD%9A', 'source_only'),
  (61, 6, '上九：翰音登于天，貞凶。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E4%B8%AD%E5%AD%9A', 'source_only'),
  (62, 1, '初六：飛鳥以凶。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B0%8F%E9%81%8E', 'source_only'),
  (62, 2, '六二：過其祖，遇其妣；不及其君，遇其臣；无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B0%8F%E9%81%8E', 'source_only'),
  (62, 3, '九三：弗過防之，從或戕之，凶。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B0%8F%E9%81%8E', 'source_only'),
  (62, 4, '九四：无咎，弗過遇之。往厲必戒，勿用永貞。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B0%8F%E9%81%8E', 'source_only'),
  (62, 5, '六五：密云不雨，自我西郊，公弋取彼在穴。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B0%8F%E9%81%8E', 'source_only'),
  (62, 6, '上六：弗遇過之，飛鳥離之，凶，是謂災眚。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B0%8F%E9%81%8E', 'source_only'),
  (63, 1, '初九：曳其輪，濡其尾，无咎。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%97%A2%E6%BF%9F', 'source_only'),
  (63, 2, '六二：婦喪其茀，勿逐，七日得。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%97%A2%E6%BF%9F', 'source_only'),
  (63, 3, '九三：高宗伐鬼方，三年克之，小人勿用。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%97%A2%E6%BF%9F', 'source_only'),
  (63, 4, '六四：繻有衣袽，終日戒。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%97%A2%E6%BF%9F', 'source_only'),
  (63, 5, '九五：東鄰殺牛，不如西鄰之禴祭，實受其福。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%97%A2%E6%BF%9F', 'source_only'),
  (63, 6, '上六：濡其首，厲。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%97%A2%E6%BF%9F', 'source_only'),
  (64, 1, '初六：濡其尾，吝。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%9C%AA%E6%BF%9F', 'source_only'),
  (64, 2, '九二：曳其輪，貞吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%9C%AA%E6%BF%9F', 'source_only'),
  (64, 3, '六三：未濟，征凶，利涉大川。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%9C%AA%E6%BF%9F', 'source_only'),
  (64, 4, '九四：貞吉，悔亡，震用伐鬼方，三年有賞于大國。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%9C%AA%E6%BF%9F', 'source_only'),
  (64, 5, '六五：貞吉，无悔，君子之光，有孚，吉。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%9C%AA%E6%BF%9F', 'source_only'),
  (64, 6, '上九：有孚于飲酒，无咎，濡其首，有孚失是。', null, 'Chu Dịch — nguyên văn Hán cổ', 'https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%9C%AA%E6%BF%9F', 'source_only')
